create or replace function public.apply_inventory_transaction(p_business_id uuid,p_product_id uuid,p_delta integer,p_reason text,p_reference text) returns jsonb language plpgsql security invoker set search_path=public as $$declare s integer; n integer;begin if not public.is_business_member(p_business_id) then raise exception 'business_access_denied';end if;select stock into s from public.products where product_id=p_product_id and business_id=p_business_id for update;if s is null then raise exception 'product_not_found';end if;n:=s+p_delta;if n<0 then raise exception 'insufficient_stock';end if;update public.products set stock=n,updated_at=now() where product_id=p_product_id and business_id=p_business_id;insert into public.inventory_transactions(business_id,product_id,delta,reason,reference) values(p_business_id,p_product_id,p_delta,p_reason,p_reference);return jsonb_build_object('product_id',p_product_id,'previous_stock',s,'new_stock',n,'delta',p_delta);end;$$;

create or replace function public.create_order_safe(p_business_id uuid,p_customer_id uuid,p_subtotal numeric,p_discount numeric,p_total numeric,p_items jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$declare i jsonb; pid uuid; q integer; s integer; o public.orders;begin if not public.is_business_member(p_business_id) then raise exception 'business_access_denied';end if;for i in select * from jsonb_array_elements(p_items) loop pid:=(i->>'product_id')::uuid;q:=(i->>'quantity')::integer;if q<=0 then raise exception 'invalid_quantity';end if;select stock into s from public.products where product_id=pid and business_id=p_business_id for update;if s is null then raise exception 'product_not_found';end if;if s-q<0 then raise exception 'insufficient_stock';end if;end loop;insert into public.orders(business_id,customer_id,subtotal,discount,total,items) values(p_business_id,p_customer_id,p_subtotal,p_discount,p_total,p_items) returning * into o;for i in select * from jsonb_array_elements(p_items) loop pid:=(i->>'product_id')::uuid;q:=(i->>'quantity')::integer;update public.products set stock=stock-q,updated_at=now() where product_id=pid and business_id=p_business_id;insert into public.inventory_transactions(business_id,product_id,delta,reason,reference) values(p_business_id,pid,-q,'order',o.order_id::text);end loop;return to_jsonb(o);end;$$;
